class Cinema {
  + town : string
}

class Theatre {
  + seatCount : int
}

class Movie {
  + name : string
}

class MovieCopy {
}

class Show {
  + startTime : datetime
}

class Reservation {
  + reservationTime : datetime
  + isCancelled : boolean
}

class CreditCard {
  + cardNumber : string
}

class Ticket {
  + seatNumber : string
  + isAnonymous : boolean
}

class Offer {
  + expiryTime : datetime
}

Cinema "1" *-- "1..*" Theatre
Cinema "1" -- "0..*" MovieCopy
Theatre "1" *-- "0..*" Show
Show "0..*" -- "1" MovieCopy
Show "1" -- "0..*" Reservation
Show "1" -- "0..*" Ticket
Show "1" -- "0..*" Offer
Reservation "0..*" -- "1" CreditCard
Reservation "0..*" -- "1" Customer
Ticket "0..*" -- "1" Show
Ticket "0..*" -- "1" Customer

class Customer {
  + name : string
}

@enduml

